import { SUPPORTED_LANGUAGES, type LanguageCode } from '@dv/i18n';
import { SearchableSelect } from '@dv/ui';
import { Languages } from 'lucide-react';
import { useTranslation } from 'react-i18next';
import { useLocation, useNavigate, useParams } from 'react-router-dom';

/**
 * Switches locale and rewrites the `/{lang}/` prefix so the URL stays shareable in the chosen
 * language. i18next persists the choice and flips `dir` on `<html>` for ar and ur.
 *
 * Drawn as a header control rather than a form field: the bar shows only the language code, and
 * the list — where there is room — spells each language out in its own name.
 */
export function LanguageSwitcher() {
  const { i18n, t } = useTranslation();
  const navigate = useNavigate();
  const location = useLocation();
  const { lang } = useParams<{ lang: string }>();

  const active = (i18n.resolvedLanguage ?? 'en') as LanguageCode;

  async function handleChange(next: string) {
    if (!next) return;
    await i18n.changeLanguage(next);

    // Swap the language segment in place, preserving the rest of the path and query.
    const segments = location.pathname.split('/').filter(Boolean);
    if (lang && segments[0] === lang) {
      segments[0] = next;
    } else {
      segments.unshift(next);
    }

    navigate(`/${segments.join('/')}${location.search}`, { replace: true });
  }

  return (
    // A label, so a click on the glyph opens the list just as a click on the code does.
    <label className="flex cursor-pointer items-center rounded-lg ps-2 text-ink-600 transition-colors hover:bg-ink-100 hover:text-ink-950">
      <span className="sr-only">{t('common.changeLanguage')}</span>
      <Languages className="size-4 shrink-0" aria-hidden="true" />
      <SearchableSelect
        value={active}
        onChange={(value) => void handleChange(value)}
        className="w-auto"
        triggerClassName="h-9 w-auto cursor-pointer gap-1 rounded-lg bg-transparent ps-1.5 pe-2 text-xs font-semibold tracking-wide text-current shadow-none! ring-0"
        menuClassName="end-0 w-56"
        aria-label={t('common.changeLanguage')}
        searchPlaceholder={t('common.search')}
        emptyMessage={t('common.noResults')}
        options={SUPPORTED_LANGUAGES.map((language) => ({
          value: language.code,
          label: language.name,
          triggerLabel: language.code.toUpperCase(),
        }))}
      />
    </label>
  );
}
